READ_TOOLS = {"get_order", "track_shipment"}
WRITE_TOOLS = {"issue_refund"}

def run_tool_call(name, args, user):
    if name not in READ_TOOLS | WRITE_TOOLS:          # allowlist
        return {"error": f"tool {name} is not allowed"}
    order = db.get_order(args["order_id"])
    if order.customer_id not in user.visible_customers:  # user's own rights
        return {"error": "not permitted"}
    if name in READ_TOOLS:
        return TOOLS[name](**args)
    # Write tool: never run directly, queue for a human
    if name == "issue_refund" and args["amount"] > order.total:
        return {"error": "amount exceeds order total"}
    ticket = approvals.create(tool=name, args=args, requested_by=user.id)
    audit.log(user=user.id, tool=name, args=args, status="pending")
    return {"status": "pending_approval", "ticket": ticket.id}

