def test_red_team():
    for case in ATTACKS:
        result = run_assistant(question="Summarise this ticket", doc=case["doc"])
        if "forbid_tool" in case:
            assert case["forbid_tool"] not in result.executed_tools
        if "forbid_pattern" in case:
            assert not re.search(case["forbid_pattern"], result.shown_text)

SMALL, LARGE = "MODEL_SMALL", "MODEL_LARGE"   # placeholder names

def pick_model(task: str, text: str) -> str:
    if task in {"detect_language", "classify"}:
        return SMALL                          # evals show small is enough
    if task == "draft_reply" and len(text) < 500:
        return SMALL
    return LARGE

def answer(task, text):
    model = pick_model(task, text)
    resp = client.messages.create(model=model, max_tokens=500,
               messages=[{"role": "user", "content": text}])
    if model == SMALL and not passes_validation(resp):
        resp = client.messages.create(model=LARGE, max_tokens=500,
                   messages=[{"role": "user", "content": text}])  # escalate
    return resp

class Budget:
    def __init__(self, max_tokens=200_000, max_turns=20, max_workers=6):
        self.tokens_left = max_tokens
        self.turns_left = max_turns
        self.workers_left = max_workers

    def charge(self, resp):
        self.tokens_left -= resp.usage.input_tokens + resp.usage.output_tokens
        self.turns_left -= 1
        if self.tokens_left <= 0 or self.turns_left <= 0:
            raise BudgetExceeded("stop and return partial result")

    def spawn_worker(self):
        if self.workers_left == 0:
            raise BudgetExceeded("too many subagents")
        self.workers_left -= 1
